C","url":"https://morningtablekitchen.com","logo":"https://morningtablekitchen.com/icons/logo-512.png","address":{"@type":"PostalAddress","streetAddress":"100 Main Street, Suite 1","addressLocality":"Anytown","addressRegion":"ST","postalCode":"00000","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","contactType":"customer service","telephone":"(555) 010-0100","email":"support@morningtablekitchen.com","areaServed":"US","availableLanguage":"English","hoursAvailable":{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"09:00","closes":"17:00"}}]}</script><script type="application/ld+json">{"@context":"https://schema.org","@type":"WebSite","name":"Morning Table Kitchen Goods","url":"https://morningtablekitchen.com","inLanguage":"en-US","publisher":{"@type":"Organization","name":"Sample Company LLC"}}</script></head><body><a class="skip-link" href="#main">Skip to main content</a><div class="shell"><header class="_rail_xdosf_5 site-rail"><a class="_wordmark_xdosf_36 u-nolink" href="/" data-discover="true"><span class="_wordmarkFirst_xdosf_45">Morning Table</span><span class="_wordmarkSecond_xdosf_52">Kitchen Goods</span></a><button type="button" class="_disclosure_xdosf_63" aria-expanded="false" aria-controls="_R_2l5_"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-menu" aria-hidden="true"><path d="M4 5h16"></path><path d="M4 12h16"></path><path d="M4 19h16"></path></svg>Menu</button><a class="_cart_xdosf_133 u-nolink" href="/cart" data-discover="true"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-shopping-basket" aria-hidden="true"><path d="m15 11-1 9"></path><path d="m19 11-4-7"></path><path d="M2 11h20"></path><path d="m3.5 11 1.6 7.4a2 2 0 0 0 2 1.6h9.8a2 2 0 0 0 2-1.6l1.7-7.4"></path><path d="M4.5 15.5h15"></path><path d="m5 11 4-7"></path><path d="m9 11 1 9"></path></svg><span>Cart (<!-- -->0<!-- -->)</span></a><div id="_R_2l5_" class="_panel_xdosf_85 "><nav aria-label="Kitchen tasks"><ul class="_links_xdosf_95"><li><a class="_link_xdosf_95 u-nolink " href="/shop/opening-and-gripping" data-discover="true">Opening &amp; Gripping</a></li><li><a class="_link_xdosf_95 u-nolink " href="/shop/cooking-and-heating" data-discover="true">Cooking &amp; Heating</a></li><li><a class="_link_xdosf_95 u-nolink " href="/shop/measuring-and-timing" data-discover="true">Measuring &amp; Timing</a></li><li><a class="_link_xdosf_95 u-nolink " href="/shop/serving-and-drinking" data-discover="true">Serving &amp; Drinking</a></li><li><a class="_link_xdosf_95 u-nolink " href="/shop/prep-and-cutting" data-discover="true">Prep &amp; Cutting</a></li><li><a class="_link_xdosf_95 u-nolink " href="/shop" data-discover="true">Everything</a></li></ul></nav><div class="_foot_xdosf_125"><p class="_phone_xdosf_152"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-phone" aria-hidden="true"><path d="M13.832 16.568a1 1 0 0 0 1.213-.303l.355-.465A2 2 0 0 1 17 15h3a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2A18 18 0 0 1 2 4a2 2 0 0 1 2-2h3a2 2 0 0 1 2 2v3a2 2 0 0 1-.8 1.6l-.468.351a1 1 0 0 0-.292 1.233 14 14 0 0 0 6.392 6.384"></path></svg><a href="tel:5550100100">(555) 010-0100</a></p><p class="_hours_xdosf_164">Weekdays, 9 a.m. to 5 p.m. Eastern</p><div class="_wrap_1smia_1"><span class="_label_1smia_15" id="text-size-label">Text size</span><div class="_group_1smia_25" role="group" aria-labelledby="text-size-label"><button type="button" class="_button_1smia_35" aria-pressed="true"><span aria-hidden="true">A</span><span class="visually-hidden">Standard text size</span></button><button type="button" class="_button_1smia_35" aria-pressed="false"><span aria-hidden="true">A+</span><span class="visually-hidden">Larger text size</span></button><button type="button" class="_button_1smia_35" aria-pressed="false"><span aria-hidden="true">A++</span><span class="visually-hidden">Largest text size</span></button></div></div></div></div></header><main id="main"><section class="page _hero_1uq4b_50"><h1 class="_heroTitle_1uq4b_54">Tools that open, lift, and pour without a fight.</h1><p class="_heroLead_1uq4b_59">Twenty-two kitchen tools, each one listed with what it weighs, how wide the handle is, and whether it works one-handed. The same four facts on every product, so you can compare two of them without reading two descriptions.</p><p class="_heroActions_1uq4b_65"><a class="_cta_1uq4b_3" href="/shop/opening-and-gripping" data-discover="true">Start with opening and gripping</a><a class="_ctaSecondary_1uq4b_4" href="/shop" data-discover="true">See all twenty-two</a></p><p class="_heroNote_1uq4b_73">Free Standard shipping over <!-- -->$59<!-- -->. Returns for<!-- --> <!-- -->30<!-- --> days.</p><div class="_heroMedia_1uq4b_79"><img class="_heroImage_1uq4b_87" src="/images/prep-and-cutting/wide-grip-peeler-3-800w.webp" srcSet="/images/prep-and-cutting/wide-grip-peeler-3-320w.webp 320w, /images/prep-and-cutting/wide-grip-peeler-3-480w.webp 480w, /images/prep-and-cutting/wide-grip-peeler-3-800w.webp 800w, /images/prep-and-cutting/wide-grip-peeler-3-1200w.webp 1200w, /images/prep-and-cutting/wide-grip-peeler-3-1600w.webp 1600w" sizes="(min-width: 62rem) 60rem, 100vw" width="1200" height="1200" alt="Kitchen utensils hanging from a rail." loading="eager" decoding="sync" fetchPriority="high"/></div></section><section class="band band--mint _factsBand_1uq4b_95"><div class="page"><h2>Every tool lists the same four facts</h2><p class="_factsLead_1uq4b_99">They sit in a yellow box on each product page, headed<!-- --> <strong>Handling facts</strong>, always in this order.</p><ul class="_factsGrid_1uq4b_104"><li class="_factCard_1uq4b_126"><h3>Weight</h3><p>In ounces, and filled where filling applies. A pitcher weighed empty tells you nothing about carrying it to the table.</p></li><li class="_factCard_1uq4b_126"><h3>Grip width</h3><p>Inches across the part your hand closes around. Where a tool is wall-mounted or has no handle, the row says so.</p></li><li class="_factCard_1uq4b_126"><h3>One-handed</h3><p>Yes, no, or a short qualifier. A tool that needs two hands is not a worse tool; it is a different one, and you should know which you are buying.</p></li><li class="_factCard_1uq4b_126"><h3>Dishwasher safe</h3><p>Yes, no, or which part. Several items here have one component that goes in and one that does not.</p></li></ul><p class="_factsFoot_1uq4b_143">Where a question does not apply, the row still appears and says why. A missing row would stop the box being comparable, which is the only thing it is for.</p></div></section><section class="page band _tasks_1uq4b_149"><h2>What the tools are for</h2><p class="_tasksLead_1uq4b_153">The shop is sorted by the job rather than by the material or the maker, because that is how a kitchen problem announces itself.</p><ul class="_taskGrid_1uq4b_157"><li class="_taskCard_1uq4b_179"><h3><a class="u-nolink" href="/shop/opening-and-gripping" data-discover="true">Opening &amp; Gripping</a></h3><p>Lids, cans, and packaging, dealt with by leverage rather than by force.</p><p class="_taskCount_1uq4b_204">4<!-- --> <!-- -->tools</p></li><li class="_taskCard_1uq4b_179"><h3><a class="u-nolink" href="/shop/cooking-and-heating" data-discover="true">Cooking &amp; Heating</a></h3><p>Pans light enough to lift full, and a kettle that boils one cup and switches itself off.</p><p class="_taskCount_1uq4b_204">4<!-- --> <!-- -->tools</p></li><li class="_taskCard_1uq4b_179"><h3><a class="u-nolink" href="/shop/measuring-and-timing" data-discover="true">Measuring &amp; Timing</a></h3><p>Numbers big enough to read from where you are standing, not where the dial is.</p><p class="_taskCount_1uq4b_204">4<!-- --> <!-- -->tools</p></li><li class="_taskCard_1uq4b_179"><h3><a class="u-nolink" href="/shop/serving-and-drinking" data-discover="true">Serving &amp; Drinking</a></h3><p>Two handles where one is usually offered, and rims that pour where you aim them.</p><p class="_taskCount_1uq4b_204">5<!-- --> <!-- -->tools</p></li><li class="_taskCard_1uq4b_179"><h3><a class="u-nolink" href="/shop/prep-and-cutting" data-discover="true">Prep &amp; Cutting</a></h3><p>Knives and boards worked with the arm rather than the wrist.</p><p class="_taskCount_1uq4b_204">5<!-- --> <!-- -->tools</p></li></ul></section><section class="band band--alt _featured_1uq4b_212"><div class="page"><h2>Six we would buy first</h2><p class="_featuredLead_1uq4b_216">Chosen because each one solves a job that the usual version of the tool makes harder than it needs to be.</p><ul class="_productGrid_1uq4b_220"><li><article class="_card_1oze6_1"><div class="_media_1oze6_18"><img class="_image_1oze6_22" src="/images/opening-and-gripping/under-cabinet-jar-opener-1-800w.webp" srcSet="/images/opening-and-gripping/under-cabinet-jar-opener-1-320w.webp 320w, /images/opening-and-gripping/under-cabinet-jar-opener-1-480w.webp 480w, /images/opening-and-gripping/under-cabinet-jar-opener-1-800w.webp 800w, /images/opening-and-gripping/under-cabinet-jar-opener-1-1200w.webp 1200w, /images/opening-and-gripping/under-cabinet-jar-opener-1-1600w.webp 1600w" sizes="(min-width: 75rem) 20rem, (min-width: 45rem) 45vw, 100vw" width="1200" height="1200" alt="A jar being opened in a kitchen." loading="lazy" decoding="async" fetchPriority="auto"/></div><div class="_body_1oze6_28"><h3 class="_name_1oze6_36"><a class="u-nolink" href="/products/under-cabinet-jar-opener" data-discover="true">Under-Cabinet Jar Opener</a></h3><p class="_price_1oze6_53">$14.99</p><p class="_blurb_1oze6_67">Grips lids from 1 to 3.5 inches and mounts under a shelf with two screws.</p><dl class="_facts_1oze6_76"><div class="_fact_1oze6_76"><dt>Weight</dt><dd>6 oz</dd></div><div class="_fact_1oze6_76"><dt>Grip</dt><dd>Not applicable — wall mounted</dd></div><div class="_fact_1oze6_76"><dt>One-handed</dt><dd>Yes, once fitted</dd></div></dl></div></article></li><li><article class="_card_1oze6_1"><div class="_media_1oze6_18"><img class="_image_1oze6_22" src="/images/cooking-and-heating/lightweight-nonstick-skillet-1-800w.webp" srcSet="/images/cooking-and-heating/lightweight-nonstick-skillet-1-320w.webp 320w, /images/cooking-and-heating/lightweight-nonstick-skillet-1-480w.webp 480w, /images/cooking-and-heating/lightweight-nonstick-skillet-1-800w.webp 800w, /images/cooking-and-heating/lightweight-nonstick-skillet-1-1200w.webp 1200w, /images/cooking-and-heating/lightweight-nonstick-skillet-1-1600w.webp 1600w" sizes="(min-width: 75rem) 20rem, (min-width: 45rem) 45vw, 100vw" width="1200" height="1200" alt="A frying pan on a stove." loading="lazy" decoding="async" fetchPriority="auto"/></div><div class="_body_1oze6_28"><h3 class="_name_1oze6_36"><a class="u-nolink" href="/products/lightweight-nonstick-skillet" data-discover="true">Lightweight Nonstick Skillet, 10 inch</a></h3><p class="_price_1oze6_53">$24.99</p><p class="_blurb_1oze6_67">A 10-inch pan weighing 1 lb 9 oz, with a helper handle on the far rim.</p><dl class="_facts_1oze6_76"><div class="_fact_1oze6_76"><dt>Weight</dt><dd>1 lb 9 oz</dd></div><div class="_fact_1oze6_76"><dt>Grip</dt><dd>1.25 in main handle, plus a far-rim helper loop</dd></div><div class="_fact_1oze6_76"><dt>One-handed</dt><dd>Yes empty; the helper handle is there for a full pan</dd></div></dl></div></article></li><li><article class="_card_1oze6_1"><div class="_media_1oze6_18"><img class="_image_1oze6_22" src="/images/measuring-and-timing/large-display-kitchen-timer-1-800w.webp" srcSet="/images/measuring-and-timing/large-display-kitchen-timer-1-320w.webp 320w, /images/measuring-and-timing/large-display-kitchen-timer-1-480w.webp 480w, /images/measuring-and-timing/large-display-kitchen-timer-1-800w.webp 800w, /images/measuring-and-timing/large-display-kitchen-timer-1-1200w.webp 1200w, /images/measuring-and-timing/large-display-kitchen-timer-1-1600w.webp 1600w" sizes="(min-width: 75rem) 20rem, (min-width: 45rem) 45vw, 100vw" width="1200" height="1200" alt="A kitchen timer on a counter." loading="lazy" decoding="async" fetchPriority="auto"/></div><div class="_body_1oze6_28"><h3 class="_name_1oze6_36"><a class="u-nolink" href="/products/large-display-kitchen-timer" data-discover="true">Large-Display Kitchen Timer</a></h3><p class="_price_1oze6_53">$12.99</p><p class="_blurb_1oze6_67">Digits 1.8 inches tall, three preset buttons, and a magnet that actually holds.</p><dl class="_facts_1oze6_76"><div class="_fact_1oze6_76"><dt>Weight</dt><dd>4 oz with battery</dd></div><div class="_fact_1oze6_76"><dt>Grip</dt><dd>0.7 in buttons</dd></div><div class="_fact_1oze6_76"><dt>One-handed</dt><dd>Yes</dd></div></dl></div></article></li><li><article class="_card_1oze6_1"><div class="_media_1oze6_18"><img class="_image_1oze6_22" src="/images/serving-and-drinking/two-handled-mug-1-800w.webp" srcSet="/images/serving-and-drinking/two-handled-mug-1-320w.webp 320w, /images/serving-and-drinking/two-handled-mug-1-480w.webp 480w, /images/serving-and-drinking/two-handled-mug-1-800w.webp 800w, /images/serving-and-drinking/two-handled-mug-1-1200w.webp 1200w, /images/serving-and-drinking/two-handled-mug-1-1600w.webp 1600w" sizes="(min-width: 75rem) 20rem, (min-width: 45rem) 45vw, 100vw" width="1200" height="1200" alt="A ceramic mug on a table." loading="lazy" decoding="async" fetchPriority="auto"/></div><div class="_body_1oze6_28"><h3 class="_name_1oze6_36"><a class="u-nolink" href="/products/two-handled-mug" data-discover="true">Two-Handled Mug</a></h3><p class="_price_1oze6_53">$16.99</p><p class="_blurb_1oze6_67">A 10-ounce stoneware mug with a handle on each side, both sized for three fingers.</p><dl class="_facts_1oze6_76"><div class="_fact_1oze6_76"><dt>Weight</dt><dd>12 oz empty, about 1 lb 5 oz filled</dd></div><div class="_fact_1oze6_76"><dt>Grip</dt><dd>Three-finger opening on each handle</dd></div><div class="_fact_1oze6_76"><dt>One-handed</dt><dd>Yes, but two hands is the reason it exists</dd></div></dl></div></article></li><li><article class="_card_1oze6_1"><div class="_media_1oze6_18"><img class="_image_1oze6_22" src="/images/prep-and-cutting/rocker-knife-1-800w.webp" srcSet="/images/prep-and-cutting/rocker-knife-1-320w.webp 320w, /images/prep-and-cutting/rocker-knife-1-480w.webp 480w, /images/prep-and-cutting/rocker-knife-1-800w.webp 800w, /images/prep-and-cutting/rocker-knife-1-1200w.webp 1200w, /images/prep-and-cutting/rocker-knife-1-1600w.webp 1600w" sizes="(min-width: 75rem) 20rem, (min-width: 45rem) 45vw, 100vw" width="1200" height="1200" alt="A kitchen knife on a cutting board." loading="lazy" decoding="async" fetchPriority="auto"/></div><div class="_body_1oze6_28"><h3 class="_name_1oze6_36"><a class="u-nolink" href="/products/rocker-knife" data-discover="true">Rocker Knife</a></h3><p class="_price_1oze6_53">$18.99</p><p class="_blurb_1oze6_67">A curved 6-inch blade with a vertical grip, worked by rocking rather than sawing.</p><dl class="_facts_1oze6_76"><div class="_fact_1oze6_76"><dt>Weight</dt><dd>7 oz</dd></div><div class="_fact_1oze6_76"><dt>Grip</dt><dd>1.5 in vertical handle</dd></div><div class="_fact_1oze6_76"><dt>One-handed</dt><dd>Yes — that is the entire reason for the shape</dd></div></dl></div></article></li><li><article class="_card_1oze6_1"><div class="_media_1oze6_18"><img class="_image_1oze6_22" src="/images/serving-and-drinking/wide-grip-utensil-set-1-800w.webp" srcSet="/images/serving-and-drinking/wide-grip-utensil-set-1-320w.webp 320w, /images/serving-and-drinking/wide-grip-utensil-set-1-480w.webp 480w, /images/serving-and-drinking/wide-grip-utensil-set-1-800w.webp 800w, /images/serving-and-drinking/wide-grip-utensil-set-1-1200w.webp 1200w, /images/serving-and-drinking/wide-grip-utensil-set-1-1600w.webp 1600w" sizes="(min-width: 75rem) 20rem, (min-width: 45rem) 45vw, 100vw" width="1200" height="1200" alt="Kitchen utensils in a holder." loading="lazy" decoding="async" fetchPriority="auto"/></div><div class="_body_1oze6_28"><h3 class="_name_1oze6_36"><a class="u-nolink" href="/products/wide-grip-utensil-set" data-discover="true">Wide-Grip Utensil Set, Five Pieces</a></h3><p class="_price_1oze6_53">$19.99</p><p class="_blurb_1oze6_67">Slotted spoon, solid spoon, turner, ladle, and pasta fork, all on a 1.6-inch grip.</p><dl class="_facts_1oze6_76"><div class="_fact_1oze6_76"><dt>Weight</dt><dd>3 oz to 5 oz each</dd></div><div class="_fact_1oze6_76"><dt>Grip</dt><dd>1.6 in, flat-bottomed</dd></div><div class="_fact_1oze6_76"><dt>One-handed</dt><dd>Yes</dd></div></dl></div></article></li></ul><p><a href="/shop" data-discover="true">All twenty-two tools, sorted by task</a></p></div></section><section class="page band _ordering_1uq4b_253"><h2>Ordering takes three steps</h2><ol class="_steps_1uq4b_257"><li class="_step_1uq4b_257"><span class="_stepNumber_1uq4b_282" aria-hidden="true">1</span><div><h3>Add what you want to the cart</h3><p>Nothing to register for. The first time an email address is asked for is on the checkout page, and it is used for the receipt.</p></div></li><li class="_step_1uq4b_257"><span class="_stepNumber_1uq4b_282" aria-hidden="true">2</span><div><h3>See the full total before you pay</h3><p>Shipping and sales tax are both shown on the cart page and again at checkout. Standard shipping is $6.95, or free once the order passes $59.</p></div></li><li class="_step_1uq4b_257"><span class="_stepNumber_1uq4b_282" aria-hidden="true">3</span><div><h3>Pay on Stripe&#x27;s page</h3><p>Card details go to Stripe and never touch this site. If you would rather read a card number to a person, call and we will take the order by telephone.</p></div></li></ol></section><section class="band band--alt _plain_1uq4b_302"><div class="page _plainInner_1uq4b_306"><div><h2>Plain facts</h2><dl class="_plainList_1uq4b_318"><div><dt>Shipping</dt><dd>Standard<!-- --> <!-- -->$6.95<!-- -->,<!-- --> <!-- -->3–7 business days<!-- -->. <!-- -->Expedited<!-- --> <!-- -->$14.95<!-- -->,<!-- --> <!-- -->2–3 business days<!-- -->. Free Standard over<!-- --> <!-- -->$59<!-- -->.</dd></div><div><dt>Returns</dt><dd>You get <!-- -->30<!-- --> days once it arrives, and you do not have to justify the decision. Our label is<!-- --> <!-- -->$6.95<!-- -->, deducted at refund time. The exception is anything used with food, which cannot be resold and so cannot be sent back.</dd></div><div><dt>Where we ship</dt><dd>The 48 contiguous states and Washington, D.C. PO boxes by Standard shipping only. No Alaska, Hawaii, Puerto Rico, US territories, or APO/FPO addresses yet.</dd></div><div><dt>Reviews</dt><dd>None. The shop is new and has never sold anything, so there is nothing honest to put here. When real customers write, their words will appear and nobody else&#x27;s will.</dd></div></dl></div><div><h2>Photographs</h2><p>The photographs on this site show the type of tool rather than the exact unit that will arrive. They are labeled that way on every product page and will be replaced with pictures of real stock before anything is advertised.</p><p><a href="/about" data-discover="true">More about how this shop is put together</a></p></div></div></section><section class="band band--butter _help_1uq4b_344"><div class="page _helpInner_1uq4b_348"><div><h2>Rather ask a person</h2><p>Call <!-- -->(555) 010-0100<!-- --> and we will look up a weight, read out a measurement, or take the whole order over the telephone. Hours are<!-- --> <!-- -->Monday–Friday, 9 a.m.–5 p.m. Eastern Time (closed weekends and federal holidays)<!-- -->. Email gets an answer<!-- --> <!-- -->within 1 business day<!-- -->.</p></div><p class="_helpActions_1uq4b_365"><a class="_ctaOnButter_1uq4b_5" hr